 * The first cycle a name-ordered depth-first search meets, walking each task's
 * dependencies in name order.
 * @param tasks - the parsed graph.
 * @returns the cycle as names from the repeated task back to itself, or `undefined` when the graph is acyclic.
 */
export function findCycle(tasks) {
  const state = new Map() // 'visiting' or 'visited'
  const stack = [] // current path in DFS

  function visit(name) {
    const current = state.get(name)
    if (current === 'visited') return undefined
    if (current === 'visiting') {
      // Found a cycle! Reconstruct it from the current node back to itself
      const start = stack.indexOf(name)
      return stack.slice(start).concat(name)
    }

    state.set(name, 'visiting')
    stack.push(name)

    const task = tasks.get(name)
    for (const dependency of task.deps) {
      const cycle = visit(dependency)
      if (cycle !== undefined) return cycle
    }

    stack.pop()
    state.set(name, 'visited')
    return undefined
  }

  // Start DFS from each task in ascending order
  for (const name of [...tasks.keys()].sort()) {
    const cycle = visit(name)
    if (cycle !== undefined) return cycle
  }

  return undefined
}"}

